use vstd::prelude::*;

verus! {

/// Spec-level view of the function: it returns the same sequence of characters.
spec fn id_seq(s: Seq<char>) -> Seq<char> {
    s
}

fn solve(t: Vec<char>) -> (out: Vec<char>)
    ensures
        // The output has the same length and elements as the input.
        out@ == id_seq(t@),
{
    // Input is assumed non-empty by the problem statement, but the code also works for empty.
    let n = t.len();
    let mut out: Vec<char> = Vec::with_capacity(n);

    // Loop processes elements left-to-right; the decreasing measure is (n - i).
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            n == t.len(),
            out@ == t@.subrange(0, i as int),
        decreases
            n - i,
    {
        out.push(t[i]);
        i += 1;
    }

    // At loop exit, i == n, so out is the full prefix (i.e., all of t).
    assert(i == n);
    assert(out@ == t@.subrange(0, n as int));
    assert(t@.subrange(0, n as int) == t@);

    out
}

} // verus!

